101	function listAgents(dir) {
102	  try {
103	    if (!fs.existsSync(dir)) return [];
104	    return fs.readdirSync(dir)
105	      .filter(f => f.endsWith('.md'))
106	      .map(f => parseAgent(path.join(dir, f)))
107	      .filter(Boolean);
108	  } catch {
