113	function listMdFiles(dir) {
114	  try {
115	    if (!fs.existsSync(dir)) return [];
116	    return fs.readdirSync(dir)
117	      .filter(f => f.endsWith('.md'))
118	      .map(f => {
119	        const filePath = path.join(dir, f);
120	        const content = readFileSafe(filePath);
121	        const stats = fs.statSync(filePath);
122	        return {
123	          name: f.replace('.md', ''),
124	          content: content || '',
125	          path: filePath,
126	          updatedAt: stats.mtime.toISOString(),
127	        };
128	      });
129	  } catch {
130	    return [];
131	  }
132	}
