134	function discoverProjects(dirs) {
135	  const projects = [];
136	  for (const dir of dirs) {
137	    const resolved = dir.replace(/^~/, HOME);
138	    if (!fs.existsSync(resolved)) continue;
139	    try {
140	      const entries = fs.readdirSync(resolved, { withFileTypes: true });
141	      for (const entry of entries) {
142	        if (!entry.isDirectory()) continue;
143	        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
144	        const projectPath = path.join(resolved, entry.name);
145	        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
146	        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
147	        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
148	        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
149	        if (hasClaudeDir || hasClaudeMd || hasPackageJson || hasPubspec) {
150	          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
151	          const commands = listMdFiles(path.join(projectPath, '.claude', 'commands'));
152	          const rules = listMdFiles(path.join(projectPath, '.claude', 'rules'));
153	          projects.push({
154	            id: Buffer.from(projectPath).toString('base64url'),
155	            name: entry.name,
156	            path: projectPath,
157	            displayPath: projectPath.replace(HOME, '~'),
158	            hasClaudeDir,
159	            hasClaudeMd,
160	            agentCount: agents.length,
161	            commandCount: commands.length,
162	            ruleCount: rules.length,
163	            agents,
164	            commands: commands.map(c => c.name),
165	            rules: rules.map(r => r.name),
166	          });
167	        }
168	      }
169	    } catch {}
170	  }
171	  return projects;
172	}
