336	app.get('/api/browse', (req, res) => {
337	  let targetPath = (req.query.path || HOME).replace(/^~/, HOME);
338	  targetPath = path.resolve(targetPath);
339	
340	  try {
341	    if (!fs.existsSync(targetPath)) {
342	      return res.status(404).json({ error: 'Path not found' });
343	    }
344	    const stat = fs.statSync(targetPath);
345	    if (!stat.isDirectory()) {
346	      return res.status(400).json({ error: 'Not a directory' });
347	    }
348	
349	    const entries = fs.readdirSync(targetPath, { withFileTypes: true });
350	    const dirs = entries
351	      .filter(e => e.isDirectory() && !e.name.startsWith('.') && e.name !== 'node_modules' && e.name !== '__pycache__')
352	      .map(e => ({
353	        name: e.name,
354	        path: path.join(targetPath, e.name),
355	        displayPath: path.join(targetPath, e.name).replace(HOME, '~'),
356	        hasProjects: false,
357	      }))
358	      .sort((a, b) => a.name.localeCompare(b.name));
359	
360	    for (const dir of dirs) {
361	      try {
362	        const sub = fs.readdirSync(dir.path, { withFileTypes: true });
363	        dir.hasProjects = sub.some(s =>
364	          s.isDirectory() && (
365	            fs.existsSync(path.join(dir.path, s.name, '.claude')) ||
366	            fs.existsSync(path.join(dir.path, s.name, 'CLAUDE.md')) ||
367	            fs.existsSync(path.join(dir.path, s.name, 'package.json')) ||
368	            fs.existsSync(path.join(dir.path, s.name, 'pubspec.yaml'))
369	          )
370	        );
371	      } catch {}
372	    }
373	
374	    const parts = targetPath.split(path.sep).filter(Boolean);
375	    const breadcrumbs = parts.map((part, i) => ({
376	      name: i === 0 && targetPath.startsWith(HOME) ? '~' : part,
377	      path: path.sep + parts.slice(0, i + 1).join(path.sep),
378	    }));
379	
380	    if (targetPath.startsWith(HOME)) {
381	      const homeIndex = HOME.split(path.sep).filter(Boolean).length - 1;
382	      breadcrumbs.splice(0, homeIndex + 1, { name: '~', path: HOME });
383	    }
384	
385	    res.json({
386	      current: targetPath,
387	      displayPath: targetPath.replace(HOME, '~'),
388	      parent: path.dirname(targetPath) !== targetPath ? path.dirname(targetPath) : null,
389	      breadcrumbs,
390	      directories: dirs,
391	    });
392	  } catch (e) {
393	    res.status(500).json({ error: 'Cannot read directory' });
394	  }
395	});
