773	// Topological sort helper
774	function topoSort(nodes, edges) {
775	  const inDegree = {};
776	  const adj = {};
777	  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
778	  for (const e of edges) {
779	    adj[e.source].push(e.target);
780	    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
781	  }
782	  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
783	  const order = [];
784	  while (queue.length) {
785	    const id = queue.shift();
786	    order.push(id);
787	    for (const next of adj[id]) {
788	      inDegree[next]--;
789	      if (inDegree[next] === 0) queue.push(next);
790	    }
791	  }
792	  return order;
793	}
