795	function runClaudeSync(prompt) {
796	  return new Promise((resolve, reject) => {
797	    const claudePath = process.env.CLAUDE_PATH || 'claude';
798	    const childEnv = { ...process.env, HOME: os.homedir() };
799	    delete childEnv.CLAUDECODE;
800	    const proc = spawn(claudePath, ['-p'], { env: childEnv });
801	    let out = '', err = '';
802	    proc.stdout.on('data', d => { out += d.toString(); });
803	    proc.stderr.on('data', d => { err += d.toString(); });
804	    proc.on('close', code => {
805	      if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
806	      else resolve(out.trim());
807	    });
808	    proc.on('error', reject);
809	    proc.stdin.write(prompt, 'utf8');
810	    proc.stdin.end();
811	  });
812	}
