817	  if (!Array.isArray(nodes) || !task) return res.status(400).json({ error: 'nodes and task required' });
818	
819	  const nodeMap = Object.fromEntries(nodes.map(n => [n.id, n]));
820	  const order = topoSort(nodes, edges || []);
